//! Hash function used by default for the map.
//!
//! libstdc++ implements `std::hash<int>` as the identity function (the value is
//! simply widened to `size_t`). The container's bucket layout — and therefore
//! when a displacement or an early rehash happens — depends on the hash, so the
//! port reproduces that identity mapping rather than using `SipHash`.

use std::hash::{BuildHasher, Hasher};

/// Widens the hashed integer to a `u64` unchanged, like `std::hash<int>`.
#[derive(Clone, Copy, Debug, Default)]
pub struct IdentityHasher {
    state: u64,
}

impl Hasher for IdentityHasher {
    fn finish(&self) -> u64 {
        self.state
    }

    /// Fallback for types that hash as raw bytes (e.g. `str`): FNV-1a, so the
    /// container stays usable with non-integer keys.
    fn write(&mut self, bytes: &[u8]) {
        let mut h = if self.state == 0 { 0xcbf2_9ce4_8422_2325 } else { self.state };
        for &b in bytes {
            h ^= b as u64;
            h = h.wrapping_mul(0x0000_0100_0000_01b3);
        }
        self.state = h;
    }

    fn write_u8(&mut self, i: u8) {
        self.state = i as u64;
    }
    fn write_u16(&mut self, i: u16) {
        self.state = i as u64;
    }
    fn write_u32(&mut self, i: u32) {
        self.state = i as u64;
    }
    fn write_u64(&mut self, i: u64) {
        self.state = i;
    }
    fn write_usize(&mut self, i: usize) {
        self.state = i as u64;
    }
    // Signed values are sign-extended, matching `static_cast<size_t>(value)`.
    fn write_i8(&mut self, i: i8) {
        self.state = i as i64 as u64;
    }
    fn write_i16(&mut self, i: i16) {
        self.state = i as i64 as u64;
    }
    fn write_i32(&mut self, i: i32) {
        self.state = i as i64 as u64;
    }
    fn write_i64(&mut self, i: i64) {
        self.state = i as u64;
    }
    fn write_isize(&mut self, i: isize) {
        self.state = i as i64 as u64;
    }
}

/// [`BuildHasher`] producing [`IdentityHasher`]s.
#[derive(Clone, Copy, Debug, Default)]
pub struct IdentityBuildHasher;

impl BuildHasher for IdentityBuildHasher {
    type Hasher = IdentityHasher;

    fn build_hasher(&self) -> IdentityHasher {
        IdentityHasher::default()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::hash::Hash;

    fn hash_of<T: Hash>(value: T) -> u64 {
        let mut h = IdentityBuildHasher.build_hasher();
        value.hash(&mut h);
        h.finish()
    }

    #[test]
    fn integers_hash_to_themselves() {
        assert_eq!(hash_of(0i32), 0);
        assert_eq!(hash_of(42i32), 42);
        assert_eq!(hash_of(-1i32), u64::MAX);
    }
}

