//! Bucket-count policy: the default `tsl::hh::power_of_two_growth_policy<2>`.
//!
//! Bucket counts are always powers of two, so mapping a hash to a bucket is a
//! mask instead of a modulo. A requested count is rounded up to the next power
//! of two; a request of zero yields an empty table (which is the state of a
//! default-constructed map — the first insertion grows it to two buckets).

/// Growth policy keeping the bucket count a power of two and doubling on growth.
#[derive(Clone, Copy, Debug)]
pub struct PowerOfTwoGrowthPolicy {
    /// `bucket_count - 1`, or `0` for an empty table.
    mask: usize,
}

impl PowerOfTwoGrowthPolicy {
    /// Builds the policy for at least `min_bucket_count` buckets and returns it
    /// together with the bucket count actually used.
    pub fn new(min_bucket_count: usize) -> (Self, usize) {
        if min_bucket_count == 0 {
            return (Self { mask: 0 }, 0);
        }
        let bucket_count = round_up_to_power_of_two(min_bucket_count);
        (Self { mask: bucket_count - 1 }, bucket_count)
    }

    /// Bucket a hash maps to.
    pub fn bucket_for_hash(&self, hash: u64) -> usize {
        (hash as usize) & self.mask
    }

    /// Bucket count to use on the next growth: twice the current one, and two
    /// for a table that is still empty.
    pub fn next_bucket_count(&self) -> usize {
        (self.mask + 1) * 2
    }
}

/// Smallest power of two `>= value` (`1` for `value <= 1`).
pub fn round_up_to_power_of_two(value: usize) -> usize {
    if value <= 1 {
        return 1;
    }
    let mut v = value - 1;
    let mut shift = 1;
    while shift < usize::BITS as usize {
        v |= v >> shift;
        shift <<= 1;
    }
    v + 1
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn rounds_up_to_powers_of_two() {
        assert_eq!(round_up_to_power_of_two(0), 1);
        assert_eq!(round_up_to_power_of_two(1), 1);
        assert_eq!(round_up_to_power_of_two(2), 2);
        assert_eq!(round_up_to_power_of_two(3), 4);
        assert_eq!(round_up_to_power_of_two(22), 32);
        assert_eq!(round_up_to_power_of_two(32), 32);
        assert_eq!(round_up_to_power_of_two(33), 64);
    }

    #[test]
    fn empty_table_grows_to_two_buckets() {
        let (policy, count) = PowerOfTwoGrowthPolicy::new(0);
        assert_eq!(count, 0);
        assert_eq!(policy.next_bucket_count(), 2);
    }

    #[test]
    fn growth_doubles() {
        let (policy, count) = PowerOfTwoGrowthPolicy::new(20);
        assert_eq!(count, 32);
        assert_eq!(policy.next_bucket_count(), 64);
    }
}

