//! Core open-addressing hopscotch hash table.
//!
//! Every entry lives within `NEIGHBORHOOD_SIZE` buckets of the bucket its hash
//! maps to ("home" bucket). Each home bucket carries a bitmap whose bit `i`
//! records that the bucket at offset `i` holds one of its entries, so a lookup
//! only ever probes the buckets flagged in one bitmap. On insertion, if the
//! nearest free bucket is too far away it is walked back into the neighborhood
//! by displacing entries that can afford to move; when that is impossible the
//! table grows and the insertion is retried.
//!
//! The table array is over-allocated by `NEIGHBORHOOD_SIZE - 1` buckets so a
//! neighborhood never wraps past the end.

use std::hash::{BuildHasher, Hash, Hasher};

use super::growth_policy::PowerOfTwoGrowthPolicy;

/// Number of buckets a neighborhood spans (bit width of the bitmap, minus the
/// two bits the reference implementation reserves for bookkeeping).
pub const NEIGHBORHOOD_SIZE: usize = 62;

/// Load factor a freshly constructed table grows at.
pub const DEFAULT_MAX_LOAD_FACTOR: f32 = 0.9;

struct Bucket<K, V> {
    /// Bit `i` set: the bucket `i` slots after this one holds an entry whose
    /// home bucket is this one.
    neighborhood: u64,
    entry: Option<(K, V)>,
}

impl<K, V> Bucket<K, V> {
    fn empty() -> Self {
        Bucket { neighborhood: 0, entry: None }
    }
}

/// Hopscotch hash table. See [`super::hopscotch_map::HopscotchMap`] for the
/// map-flavoured wrapper.
pub struct HopscotchHash<K, V, S> {
    buckets: Vec<Bucket<K, V>>,
    bucket_count: usize,
    policy: PowerOfTwoGrowthPolicy,
    hash_builder: S,
    nb_elements: usize,
    max_load_factor: f32,
    /// Element count at which the next insertion grows the table.
    load_threshold: usize,
}

impl<K, V, S> HopscotchHash<K, V, S>
where
    K: Hash + Eq,
    S: BuildHasher,
{
    /// Creates a table with at least `bucket_count` buckets (rounded up to a
    /// power of two; zero leaves the table unallocated).
    pub fn with_bucket_count_and_hasher(bucket_count: usize, hash_builder: S) -> Self {
        let (policy, bucket_count) = PowerOfTwoGrowthPolicy::new(bucket_count);
        HopscotchHash {
            buckets: Self::new_buckets(bucket_count),
            bucket_count,
            policy,
            hash_builder,
            nb_elements: 0,
            max_load_factor: DEFAULT_MAX_LOAD_FACTOR,
            load_threshold: load_threshold(bucket_count, DEFAULT_MAX_LOAD_FACTOR),
        }
    }

    /// Number of stored elements.
    pub fn len(&self) -> usize {
        self.nb_elements
    }

    /// Whether the table holds no elements.
    pub fn is_empty(&self) -> bool {
        self.nb_elements == 0
    }

    /// Number of buckets, always a power of two (or zero).
    pub fn bucket_count(&self) -> usize {
        self.bucket_count
    }

    /// `len / bucket_count`, and `0` for a table with no buckets.
    pub fn load_factor(&self) -> f32 {
        if self.bucket_count == 0 {
            return 0.0;
        }
        self.nb_elements as f32 / self.bucket_count as f32
    }

    /// Load factor the table grows at.
    pub fn max_load_factor(&self) -> f32 {
        self.max_load_factor
    }

    /// Sets the growth load factor. Like the C++ container this only updates
    /// the growth threshold; it never shrinks or grows the table on its own,
    /// so the current load factor may temporarily exceed `mlf`.
    pub fn set_max_load_factor(&mut self, mlf: f32) {
        self.max_load_factor = mlf;
        self.load_threshold = load_threshold(self.bucket_count, mlf);
    }

    /// Rebuilds the table with `max(count, ceil(len / max_load_factor))`
    /// buckets, rounded up to a power of two.
    pub fn rehash(&mut self, count: usize) {
        let needed = (self.nb_elements as f32 / self.max_load_factor).ceil() as usize;
        self.rehash_impl(count.max(needed));
    }

    /// Grows the table so `count` elements fit without a further rehash.
    pub fn reserve(&mut self, count: usize) {
        self.rehash((count as f32 / self.max_load_factor).ceil() as usize);
    }

    /// Removes every element, keeping the buckets allocated.
    pub fn clear(&mut self) {
        for bucket in &mut self.buckets {
            bucket.neighborhood = 0;
            bucket.entry = None;
        }
        self.nb_elements = 0;
    }

    /// Inserts `(key, value)`, returning `false` and keeping the stored value
    /// if an equal key is already present (`std::unordered_map::insert`).
    pub fn insert(&mut self, key: K, value: V) -> bool {
        let hash = self.hash_key(&key);
        if self.bucket_count != 0 {
            let home = self.policy.bucket_for_hash(hash);
            if self.find_in_neighborhood(home, &key).is_some() {
                return false;
            }
        }
        if self.nb_elements >= self.load_threshold {
            self.rehash_impl(self.policy.next_bucket_count());
        }
        self.insert_absent(hash, key, value);
        true
    }

    /// Inserts `(key, value)`, overwriting and returning any previous value.
    pub fn insert_or_assign(&mut self, key: K, value: V) -> Option<V> {
        let hash = self.hash_key(&key);
        if self.bucket_count != 0 {
            let home = self.policy.bucket_for_hash(hash);
            if let Some(slot) = self.find_in_neighborhood(home, &key) {
                let entry = self.buckets[slot].entry.as_mut().expect("occupied slot");
                return Some(std::mem::replace(&mut entry.1, value));
            }
        }
        if self.nb_elements >= self.load_threshold {
            self.rehash_impl(self.policy.next_bucket_count());
        }
        self.insert_absent(hash, key, value);
        None
    }

    /// Reference to the value stored for `key`.
    pub fn get(&self, key: &K) -> Option<&V> {
        let slot = self.slot_of(key)?;
        self.buckets[slot].entry.as_ref().map(|(_, v)| v)
    }

    /// Mutable reference to the value stored for `key`.
    pub fn get_mut(&mut self, key: &K) -> Option<&mut V> {
        let slot = self.slot_of(key)?;
        self.buckets[slot].entry.as_mut().map(|(_, v)| v)
    }

    /// Whether `key` is present.
    pub fn contains_key(&self, key: &K) -> bool {
        self.slot_of(key).is_some()
    }

    /// Removes `key`, returning its value.
    pub fn remove(&mut self, key: &K) -> Option<V> {
        if self.bucket_count == 0 {
            return None;
        }
        let home = self.policy.bucket_for_hash(self.hash_key(key));
        let slot = self.find_in_neighborhood(home, key)?;
        let (_, value) = self.buckets[slot].entry.take().expect("occupied slot");
        self.buckets[home].neighborhood &= !(1u64 << (slot - home));
        self.nb_elements -= 1;
        Some(value)
    }

    /// Iterates the stored entries in bucket order.
    pub fn iter(&self) -> impl Iterator<Item = (&K, &V)> {
        self.buckets.iter().filter_map(|b| b.entry.as_ref().map(|(k, v)| (k, v)))
    }

    fn hash_key(&self, key: &K) -> u64 {
        let mut hasher = self.hash_builder.build_hasher();
        key.hash(&mut hasher);
        hasher.finish()
    }

    fn slot_of(&self, key: &K) -> Option<usize> {
        if self.bucket_count == 0 {
            return None;
        }
        let home = self.policy.bucket_for_hash(self.hash_key(key));
        self.find_in_neighborhood(home, key)
    }

    /// Probes only the buckets flagged in `home`'s bitmap.
    fn find_in_neighborhood(&self, home: usize, key: &K) -> Option<usize> {
        let mut neighborhood = self.buckets[home].neighborhood;
        while neighborhood != 0 {
            let offset = neighborhood.trailing_zeros() as usize;
            neighborhood &= neighborhood - 1;
            let slot = home + offset;
            if let Some((k, _)) = &self.buckets[slot].entry {
                if k == key {
                    return Some(slot);
                }
            }
        }
        None
    }

    /// Places an entry known not to be in the table, growing as needed.
    fn insert_absent(&mut self, hash: u64, key: K, value: V) {
        loop {
            let home = self.policy.bucket_for_hash(hash);
            if let Some(empty) = self.find_empty_bucket(home) {
                if let Some(slot) = self.move_empty_into_neighborhood(home, empty) {
                    self.buckets[slot].entry = Some((key, value));
                    self.buckets[home].neighborhood |= 1u64 << (slot - home);
                    self.nb_elements += 1;
                    return;
                }
            }
            // Either the table is full past this bucket, or no entry could be
            // displaced to free a slot close enough. Grow and try again.
            self.rehash_impl(self.policy.next_bucket_count());
        }
    }

    /// First free bucket at or after `home`.
    fn find_empty_bucket(&self, home: usize) -> Option<usize> {
        (home..self.buckets.len()).find(|&i| self.buckets[i].entry.is_none())
    }

    /// Walks the free bucket `empty` back until it lies within `home`'s
    /// neighborhood, returning its final index (`None` if it cannot be moved
    /// close enough).
    fn move_empty_into_neighborhood(&mut self, home: usize, empty: usize) -> Option<usize> {
        let mut empty = empty;
        while empty - home >= NEIGHBORHOOD_SIZE {
            empty = self.swap_empty_closer(empty)?;
        }
        Some(empty)
    }

    /// Moves some entry from a bucket before `empty` into `empty`, freeing the
    /// bucket it came from. Returns the newly freed (closer) bucket.
    fn swap_empty_closer(&mut self, empty: usize) -> Option<usize> {
        // Only entries whose home is within a neighborhood of `empty` may be
        // relocated into it.
        let first_candidate = empty + 1 - NEIGHBORHOOD_SIZE;
        for candidate in first_candidate..empty {
            // Offsets that would move the entry closer to its own home bucket.
            let reachable = (1u64 << (empty - candidate)) - 1;
            let movable = self.buckets[candidate].neighborhood & reachable;
            if movable == 0 {
                continue;
            }
            let offset = movable.trailing_zeros() as usize;
            let from = candidate + offset;
            self.buckets[empty].entry = self.buckets[from].entry.take();
            self.buckets[candidate].neighborhood &= !(1u64 << offset);
            self.buckets[candidate].neighborhood |= 1u64 << (empty - candidate);
            return Some(from);
        }
        None
    }

    /// Rebuilds the table with `bucket_count` buckets (rounded up to a power of
    /// two) and re-inserts every entry.
    fn rehash_impl(&mut self, bucket_count: usize) {
        let (policy, bucket_count) = PowerOfTwoGrowthPolicy::new(bucket_count);
        let old_buckets = std::mem::replace(&mut self.buckets, Self::new_buckets(bucket_count));
        self.policy = policy;
        self.bucket_count = bucket_count;
        self.nb_elements = 0;
        self.load_threshold = load_threshold(bucket_count, self.max_load_factor);

        for bucket in old_buckets {
            if let Some((key, value)) = bucket.entry {
                let hash = self.hash_key(&key);
                self.insert_absent(hash, key, value);
            }
        }
    }

    fn new_buckets(bucket_count: usize) -> Vec<Bucket<K, V>> {
        let len = if bucket_count == 0 { 0 } else { bucket_count + NEIGHBORHOOD_SIZE - 1 };
        (0..len).map(|_| Bucket::empty()).collect()
    }
}

/// Element count at which a table of `bucket_count` buckets grows, i.e.
/// `static_cast<size_type>(bucket_count * max_load_factor)` — truncated, and
/// computed in `float` just like the C++ container.
fn load_threshold(bucket_count: usize, max_load_factor: f32) -> usize {
    (bucket_count as f32 * max_load_factor) as usize
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::tsl::identity_hash::IdentityBuildHasher;

    fn table() -> HopscotchHash<i32, i32, IdentityBuildHasher> {
        HopscotchHash::with_bucket_count_and_hasher(0, IdentityBuildHasher)
    }

    #[test]
    fn starts_empty_with_no_buckets() {
        let t = table();
        assert_eq!(t.bucket_count(), 0);
        assert_eq!(t.len(), 0);
        assert_eq!(t.load_factor(), 0.0);
    }

    #[test]
    fn grows_by_doubling_at_the_threshold() {
        let mut t = table();
        let expected = [2, 4, 4, 8, 8, 8, 8, 16, 16, 16, 16, 16, 16, 16, 32];
        for (i, &buckets) in expected.iter().enumerate() {
            t.insert(i as i32, 0);
            assert_eq!(t.bucket_count(), buckets, "after inserting {} elements", i + 1);
        }
    }

