    fn lookup_and_removal_survive_growth() {
        let mut t = table();
        for i in 0..500 {
            t.insert(i, i * 9);
        }
        assert_eq!(t.len(), 500);
        for i in 0..500 {
            assert_eq!(t.get(&i), Some(&(i * 9)));
        }
        assert_eq!(t.get(&500), None);
        for i in 0..250 {
            assert_eq!(t.remove(&i), Some(i * 9));
        }
        assert_eq!(t.len(), 250);
        assert!(!t.contains_key(&0));
        assert!(t.contains_key(&250));
    }

