            // Offsets that would move the entry closer to its own home bucket.
            let reachable = (1u64 << (empty - candidate)) - 1;
            let movable = self.buckets[candidate].neighborhood & reachable;
            if movable == 0 {
                continue;
            }
            let offset = movable.trailing_zeros() as usize;
            let from = candidate + offset;
            self.buckets[empty].entry = self.buckets[from].entry.take();
            self.buckets[candidate].neighborhood &= !(1u64 << offset);
            self.buckets[candidate].neighborhood |= 1u64 << (empty - candidate);
            return Some(from);
        }
        None
    }

    /// Rebuilds the table with `bucket_count` buckets (rounded up to a power of
    /// two) and re-inserts every entry.
    fn rehash_impl(&mut self, bucket_count: usize) {
        let (policy, bucket_count) = PowerOfTwoGrowthPolicy::new(bucket_count);
        let old_buckets = std::mem::replace(&mut self.buckets, Self::new_buckets(bucket_count));
        self.policy = policy;
        self.bucket_count = bucket_count;
        self.nb_elements = 0;
        self.load_threshold = load_threshold(bucket_count, self.max_load_factor);

        for bucket in old_buckets {
            if let Some((key, value)) = bucket.entry {
                let hash = self.hash_key(&key);
                self.insert_absent(hash, key, value);
            }
        }
    }

    fn new_buckets(bucket_count: usize) -> Vec<Bucket<K, V>> {
        let len = if bucket_count == 0 { 0 } else { bucket_count + NEIGHBORHOOD_SIZE - 1 };
        (0..len).map(|_| Bucket::empty()).collect()
    }
}

