/// `static_cast<size_type>(bucket_count * max_load_factor)` — truncated, and
/// computed in `float` just like the C++ container.
fn load_threshold(bucket_count: usize, max_load_factor: f32) -> usize {
    (bucket_count as f32 * max_load_factor) as usize
}

