//! `tsl::hopscotch_map` equivalent: a key/value map over
//! [`HopscotchHash`](super::hopscotch_hash::HopscotchHash).

use std::hash::{BuildHasher, Hash};

use super::hopscotch_hash::HopscotchHash;
use super::identity_hash::IdentityBuildHasher;

/// Hash map with hopscotch open addressing.
///
/// Defaults match the C++ container: no buckets until the first insertion, a
/// power-of-two bucket count, and a `0.9` maximum load factor.
pub struct HopscotchMap<K, V, S = IdentityBuildHasher> {
    hash: HopscotchHash<K, V, S>,
}

impl<K, V> HopscotchMap<K, V, IdentityBuildHasher>
where
    K: Hash + Eq,
{
    /// Creates an empty map (no buckets allocated).
    pub fn new() -> Self {
        Self::with_bucket_count(0)
    }

    /// Creates an empty map with at least `bucket_count` buckets.
