//! Exact decimal expansion of a binary floating-point value.
//!
//! Every finite `f64` is `mantissa * 2^exp2` and therefore has a *finite*
//! decimal expansion, which is what C's `printf` rounds from. Reproducing the
//! rounding exactly (including ties) needs those exact digits rather than a
//! shortest round-trip representation such as Rust's `{}`: `0.2578125` must
//! print as `0.257812` and `0.2734375` as `0.273438` — both are ties, broken
//! towards the even digit.
//!
//! Digits are produced with schoolbook arithmetic on a decimal big integer,
//! using `m * 2^-k == (m * 5^k) / 10^k` for negative exponents.

/// Exact decimal digits of a finite, strictly positive `value`.
///
/// Returns the digits (most significant first, no leading zeros) and an
/// exponent `e` such that `value == 0.<digits> * 10^e`.
pub fn exact_digits(value: f64) -> (Vec<u8>, i32) {
    assert!(value.is_finite() && value > 0.0, "expects a finite positive value");

    let bits = value.to_bits();
    let exponent_field = ((bits >> 52) & 0x7ff) as i32;
    let fraction = bits & ((1u64 << 52) - 1);
    // Subnormals have no implicit leading one and a fixed exponent.
    let (mantissa, exp2) = if exponent_field == 0 {
        (fraction, -1074)
    } else {
        (fraction | (1u64 << 52), exponent_field - 1075)
    };

    // Little-endian digits of the mantissa, least significant first.
    let mut digits = Vec::with_capacity(64);
    let mut rest = mantissa;
    while rest > 0 {
        digits.push((rest % 10) as u8);
        rest /= 10;
    }

    let mut decimal_shift = 0i32;
    if exp2 > 0 {
        for _ in 0..exp2 {
            multiply_by(&mut digits, 2);
        }
    } else if exp2 < 0 {
        for _ in 0..-exp2 {
            multiply_by(&mut digits, 5);
        }
        decimal_shift = exp2;
    }

    let exponent = digits.len() as i32 + decimal_shift;
    digits.reverse();
    (digits, exponent)
}

/// Multiplies a little-endian decimal digit vector in place.
fn multiply_by(digits: &mut Vec<u8>, factor: u32) {
    let mut carry = 0u32;
    for digit in digits.iter_mut() {
        let product = *digit as u32 * factor + carry;
        *digit = (product % 10) as u8;
        carry = product / 10;
    }
    while carry > 0 {
        digits.push((carry % 10) as u8);
        carry /= 10;
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn rendered(value: f64) -> (String, i32) {
        let (digits, exponent) = exact_digits(value);
        (digits.iter().map(|d| (b'0' + d) as char).collect(), exponent)
    }

    #[test]
    fn expands_exact_binary_fractions() {
        assert_eq!(rendered(0.5), ("5".to_string(), 0));
        assert_eq!(rendered(0.6875), ("6875".to_string(), 0));
        assert_eq!(rendered(0.34375), ("34375".to_string(), 0));
        assert_eq!(rendered(1.0), ("1".to_string(), 1));
        assert_eq!(rendered(1024.0), ("1024".to_string(), 4));
    }

    #[test]
    fn expands_ties_in_full() {
        assert_eq!(rendered(33.0f32 as f64 / 128.0), ("2578125".to_string(), 0));
        assert_eq!(rendered(35.0f32 as f64 / 128.0), ("2734375".to_string(), 0));
    }

    #[test]
    fn expands_values_that_are_not_exact_in_binary() {
        // 0.1 is stored as 0.1000000000000000055511151231257827021181583404541015625
        let (digits, exponent) = rendered(0.1);
        assert_eq!(exponent, 0);
        assert!(digits.starts_with("1000000000000000055511151231257827021181583404541015625"));
        assert_eq!(digits.len(), 55);
    }

    #[test]
    fn expands_the_smallest_subnormal() {
        let (digits, exponent) = rendered(f64::from_bits(1));
        assert!(digits.starts_with("49406564584124654"));
        assert_eq!(exponent, -323);
    }
}

