//! Default `std::ostream` formatting for floating-point values.
//!
//! `std::cout << some_float` promotes to `double` and formats with `%g` at the
//! stream's default precision of 6: the shorter of fixed and scientific
//! notation, rounded to 6 significant digits with trailing zeros removed.
//! Rounding is round-half-to-even applied to the value's *exact* decimal
//! expansion, which is why [`super::decimal`] exists.

use super::decimal::exact_digits;

/// Stream default precision (`std::ios_base::precision()`).
pub const DEFAULT_PRECISION: usize = 6;

/// Formats a `float` the way `std::cout << value` does.
pub fn format_float(value: f32) -> String {
    // The promotion to `double` is exact, so the printed digits are the same.
    format_g(value as f64, DEFAULT_PRECISION)
}

/// Formats a `double` the way `std::cout << value` does.
pub fn format_double(value: f64) -> String {
    format_g(value, DEFAULT_PRECISION)
}

/// `printf("%.*g", precision, value)`.
pub fn format_g(value: f64, precision: usize) -> String {
    let significant = precision.max(1);
    let sign = if value.is_sign_negative() { "-" } else { "" };

    if value.is_nan() {
        return format!("{sign}nan");
    }
    if value.is_infinite() {
        return format!("{sign}inf");
    }
    if value == 0.0 {
        return format!("{sign}0");
    }

    let (exact, exact_exponent) = exact_digits(value.abs());
    let (mut digits, carried) = round_to_significant(&exact, significant);
    // Exponent of the leading digit in scientific notation; a rounding carry
    // (999999 -> 1000000) shifts it up by one.
    let exponent = exact_exponent - 1 + i32::from(carried);

    // `%g` drops trailing zeros when the `#` flag is absent.
    while digits.len() > 1 && *digits.last().expect("non-empty") == 0 {
        digits.pop();
    }

    let mut out = String::from(sign);
    if exponent < -4 || exponent >= significant as i32 {
        out.push(digit_char(digits[0]));
        if digits.len() > 1 {
            out.push('.');
            out.extend(digits[1..].iter().map(|&d| digit_char(d)));
        }
        out.push('e');
        out.push(if exponent < 0 { '-' } else { '+' });
        let magnitude = exponent.unsigned_abs();
        if magnitude < 10 {
            out.push('0'); // exponents carry at least two digits
        }
        out.push_str(&magnitude.to_string());
    } else if exponent >= 0 {
        let integer_len = exponent as usize + 1;
        for i in 0..integer_len {
            out.push(digit_char(digits.get(i).copied().unwrap_or(0)));
        }
        if digits.len() > integer_len {
            out.push('.');
            out.extend(digits[integer_len..].iter().map(|&d| digit_char(d)));
        }
    } else {
        out.push_str("0.");
        for _ in 0..-exponent - 1 {
            out.push('0');
        }
        out.extend(digits.iter().map(|&d| digit_char(d)));
    }
    out
}

/// Rounds `digits` to `significant` digits, half-to-even. The flag reports a
/// carry out of the leading digit, i.e. the value gained a decimal place.
fn round_to_significant(digits: &[u8], significant: usize) -> (Vec<u8>, bool) {
    if digits.len() <= significant {
        return (digits.to_vec(), false);
    }

    let mut kept = digits[..significant].to_vec();
    let dropped = &digits[significant..];
    let round_up = match dropped[0].cmp(&5) {
        std::cmp::Ordering::Greater => true,
        std::cmp::Ordering::Less => false,
        // Exactly half: round to even, unless something further out tips it.
        std::cmp::Ordering::Equal => {
            dropped[1..].iter().any(|&d| d != 0) || kept[significant - 1] % 2 == 1
        }
    };
    if !round_up {
        return (kept, false);
    }

    for i in (0..significant).rev() {
        if kept[i] == 9 {
            kept[i] = 0;
        } else {
            kept[i] += 1;
            return (kept, false);
        }
    }
    // All nines rolled over: 0.999999 -> 0.100000 with one more decimal place.
    kept[0] = 1;
    (kept, true)
}

fn digit_char(digit: u8) -> char {
    (b'0' + digit) as char
}

