//! `std::stoi` semantics.
//!
//! `stoi` is `strtol` plus a range check: leading whitespace is skipped, an
//! optional sign is accepted, then the longest run of decimal digits is
//! consumed and whatever follows is ignored. No digits at all throws
//! `std::invalid_argument`; a value outside `int` throws `std::out_of_range`.

/// Failure modes of [`stoi`], named after the exceptions C++ throws.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum StoiError {
    /// `std::invalid_argument`: no digits could be read.
    Invalid,
    /// `std::out_of_range`: the value does not fit in an `int`.
    OutOfRange,
}

/// Parses a leading base-10 integer the way `std::stoi(text)` does.
pub fn stoi(text: &str) -> Result<i32, StoiError> {
    /// Accumulation stops here: far beyond `int`, far below `i64` overflow.
    const OVERFLOW_LIMIT: i64 = 1 << 40;

    let bytes = text.as_bytes();
    let mut i = 0;
    while i < bytes.len() && is_space(bytes[i]) {
        i += 1;
    }

    let mut negative = false;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        negative = bytes[i] == b'-';
        i += 1;
    }

    let first_digit = i;
    let mut magnitude: i64 = 0;
    let mut overflowed = false;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        if !overflowed {
            magnitude = magnitude * 10 + (bytes[i] - b'0') as i64;
            overflowed = magnitude > OVERFLOW_LIMIT;
        }
        i += 1;
    }

    if i == first_digit {
        return Err(StoiError::Invalid);
    }
    if overflowed {
        return Err(StoiError::OutOfRange);
    }

    let value = if negative { -magnitude } else { magnitude };
    if value < i32::MIN as i64 || value > i32::MAX as i64 {
        return Err(StoiError::OutOfRange);
    }
    Ok(value as i32)
}

/// `isspace` in the C locale.
fn is_space(byte: u8) -> bool {
    matches!(byte, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_plain_integers() {
        assert_eq!(stoi("0"), Ok(0));
        assert_eq!(stoi("11"), Ok(11));
        assert_eq!(stoi("-5"), Ok(-5));
        assert_eq!(stoi("+8"), Ok(8));
    }

    #[test]
    fn skips_whitespace_and_stops_at_the_first_non_digit() {
        assert_eq!(stoi(" 7"), Ok(7));
        assert_eq!(stoi("  12  "), Ok(12));
        assert_eq!(stoi("3x"), Ok(3));
        assert_eq!(stoi("12.9"), Ok(12));
        assert_eq!(stoi("0x10"), Ok(0));
        assert_eq!(stoi("1e3"), Ok(1));
        assert_eq!(stoi("  -0"), Ok(0));
    }

    #[test]
    fn rejects_input_without_digits() {
        assert_eq!(stoi(""), Err(StoiError::Invalid));
        assert_eq!(stoi("  "), Err(StoiError::Invalid));
        assert_eq!(stoi("abc"), Err(StoiError::Invalid));
        assert_eq!(stoi("--a"), Err(StoiError::Invalid));
        assert_eq!(stoi("+"), Err(StoiError::Invalid));
        assert_eq!(stoi("-"), Err(StoiError::Invalid));
    }

    #[test]
    fn rejects_values_outside_int() {
        assert_eq!(stoi("2147483647"), Ok(i32::MAX));
        assert_eq!(stoi("-2147483648"), Ok(i32::MIN));
        assert_eq!(stoi("2147483648"), Err(StoiError::OutOfRange));
        assert_eq!(stoi("-2147483649"), Err(StoiError::OutOfRange));
        assert_eq!(stoi("99999999999"), Err(StoiError::OutOfRange));
        assert_eq!(stoi("999999999999999999999999999"), Err(StoiError::OutOfRange));
    }
}

