//! `std::terminate` as reached through an uncaught exception.
//!
//! `test11.cpp` catches nothing, so a throwing `std::stoi` (or constructing a
//! `std::string` from a null `argv[2]`) unwinds out of `main`: libstdc++'s
//! verbose terminate handler prints the exception type and `what()` to stderr,
//! then aborts with `SIGABRT`. This reproduces both the message and the signal.

use std::io::{self, Write};
use std::process;

/// Prints libstdc++'s verbose terminate message and aborts.
pub fn uncaught_exception(exception_type: &str, what: &str) -> ! {
    let mut stderr = io::stderr().lock();
    let _ = writeln!(stderr, "terminate called after throwing an instance of '{exception_type}'");
    let _ = writeln!(stderr, "  what():  {what}");
    let _ = stderr.flush();
    process::abort();
}

