//! Rust port of `tests/test11.cpp` from the hopscotch-map test suite.
//!
//! Fills a `tsl::hopscotch_map<int, int>` with `count` entries (default 11,
//! overridable with `--a <count>`), prints the resulting load factor, then
//! lowers `max_load_factor` to 0.5, forces a `rehash(0)` and prints the load
//! factor again.
//!
//! Builds either standalone (`rustc -O test11.rs`) or through Cargo
//! (`cargo build --release`); the library modules live under `src/`.

// The library exposes a fuller container API than this one test drives.
#[allow(dead_code)]
#[path = "src/lib.rs"]
mod hopscotch;

use hopscotch::cxx::ostream::format_float;
use hopscotch::cxx::stoi::{stoi, StoiError};
use hopscotch::cxx::terminate;
use hopscotch::tsl::HopscotchMap;

fn main() {
    let argv: Vec<String> = std::env::args().collect();

    let mut count: i32 = 11;
    if argv.len() > 1 && argv[1] == "--a" {
        count = parse_count(argv.get(2));
    }

    let mut map: HopscotchMap<i32, i32> = HopscotchMap::new();
    for i in 0..count {
        map.insert((i, i.wrapping_mul(9)));
    }

    print!("{} ", format_float(map.load_factor()));
    map.set_max_load_factor(0.5);
    map.rehash(0);
    println!("{}", format_float(map.load_factor()));
}

/// `std::stoi(argv[2])`. A missing `argv[2]` is a null pointer in C++, so the
/// `std::string` conversion throws before `stoi` is even reached.
fn parse_count(arg: Option<&String>) -> i32 {
    let text = match arg {
        Some(text) => text,
        None => terminate::uncaught_exception(
            "std::logic_error",
            "basic_string::_S_construct null not valid",
        ),
    };
    match stoi(text) {
        Ok(count) => count,
        Err(StoiError::Invalid) => terminate::uncaught_exception("std::invalid_argument", "stoi"),
        Err(StoiError::OutOfRange) => terminate::uncaught_exception("std::out_of_range", "stoi"),
    }
}

